#!/usr/bin/env python3
"""ciu installer — get.py  (generated by cmru get-py)

Transactional, fail-closed installer: private-repo asset auth, per-release
directories (own venv each) with an atomic `current` symlink, state + rollback,
system/user scope, offline hash-locked wheel install, SHA256 verification of the
bundle and a verified manifest that covers everything that runs, and an optional
minisign signature over that manifest (verified whenever a key is configured).

Usage
-----
Install (system scope, requires root):
    sudo python3 get.py install [--config HOST.toml]

Install (user scope):
    python3 get.py install --scope user

Pin a specific version (installs exactly that tag):
    sudo python3 get.py install --version ciu-v0.2.0

Select a variant (multi-variant releases — one asset per interpreter):
    sudo python3 get.py install --variant py311

Update (latest, or --version X):
    sudo python3 get.py update

Status:
    python3 get.py status

Rollback (to the recorded previous release):
    sudo python3 get.py rollback

Requires: python3 (stdlib only); system tools: python3
"""
from __future__ import annotations

